-yyyy" autocomplete="off"></div><div class="form-group col-md-6"><label for="pharmacy-audit-to">To</label><input class="form-control datepicker" id="pharmacy-audit-to" type="text" name="to" value="<?= esc($filters['to'] ?? '') ?>" placeholder="dd-mm-yyyy" autocomplete="off"></div></div></div><div class="modal-footer"><a class="btn btn-light" href="<?= current_url() ?>">Clear</a><button class="btn btn-primary" type="submit">Apply filters</button></div></form></div></div></div>
